class DesignDocGenerator:
    """Generates DESIGN.md from the live data tables (tower catalog, enemy types,
wave data, maps) so the reference always matches what the code does.
Usage: java -cp build lindefense.tools.DesignDocGenerator [DESIGN.md]."""
    def __init__(self):
        pass
    @staticmethod
    def main(args):
        out = _j.File((args[0] if (len(args) > 0) else 'DESIGN.md'))
        dd = Difficulty.parse((args[1] if (len(args) > 1) else _j.get_property('design.difficulty')))
        if dd is not None:
            DesignDocGenerator.table_mode = dd
        w = PrintWriter(out, 'UTF-8')
        try:
            DesignDocGenerator.write(w)
        finally:
            pass
        print(_j.s(_j.cat('Wrote ', out.get_absolute_path())))
    @staticmethod
    def f(v):
        if abs((v - _j.rint(v))) < 1e-9:
            return _j.s(_j.to_long(_j.rint(v)))
        return _j.replace_all(_j.replace_all(_j.format('%.2f', v), '0+$', ''), '\\.$', '')
    @staticmethod
    def pct(v):
        return _j.cat(_j.to_int(_j.jround((v * 100))), '%')
    @staticmethod
    def write(w):
        w.println('# Lindefense Design Reference')
        w.println()
        w.println("_Generated by `lindefense.tools.DesignDocGenerator` from the game's data tables_")
        w.println('(`TowerCatalog`, `EnemyType`, `WaveData`, `MapCatalog`). Regenerate with `java -cp build lindefense.tools.DesignDocGenerator`.')
        w.println()
        w.println('The tower section follows the tower specification (sections 3-4: base + exactly 3 upgrades per tower, global tower')
        w.println('rules 3.0). Tower numbers live in `lindefense.tower.data.*` (one file per faction); enemy, boss, map and wave numbers')
        w.println('were authored for this implementation and live in `EnemyType`, `WaveData` and `MapCatalog`. All of it can be replaced')
        w.println('without touching game logic.')
        w.println()
        w.println('## Contents')
        w.println('1. [Global rules](#1-global-rules)')
        w.println('2. [Towers](#2-towers)')
        w.println('3. [Enemies](#3-enemies)')
