    @staticmethod
    def children(e):
        if not e.has_children():
            return '-'
        sb = _j.StringBuilder()
        i = 0
        while i < len(e.get_child_types()):
            if i > 0:
                sb.append(' + ')
            sb.append(e.get_child_counts()[i]).append(' x ').append(e.get_child_types()[i].display_name)
            i += 1
        return sb.to_string()
    @staticmethod
    def resist(e):
        r = _j.ArrayList()
        if e.get_armor() > 0:
            _j_add(r, _j.cat('armour ', DesignDocGenerator.pct(e.get_armor())))
        if e.get_weak_hit_threshold() > 0:
            _j_add(r, _j.cat('hits < ', e.get_weak_hit_threshold(), ' dmg halved'))
        if e.is_lead_body():
            _j_add(r, 'Lead-type')
        if e.is_ceramic_body():
            _j_add(r, 'Ceramic-type')
        if e.has_innate_camo():
            _j_add(r, 'always Camo')
        return '-' if (len(r) == 0) else ', '.join(r)
    @staticmethod
    def mechanic(e):
        _sw2 = e.mechanic
        if _sw2 is Mechanic.ACCELERATE_ON_DAMAGE:
            return '+15% speed per hit taken (max +90%)'
        elif _sw2 is Mechanic.BUBBLE_SWAP:
            return 'every 3 s swaps track position with the nearest enemy ahead within 45 px'
        elif _sw2 is Mechanic.SELECTION_FRONT:
            return 'every 2.5 s jumps 6 px ahead of the furthest enemy within 140 px in front'
        elif _sw2 is Mechanic.INSERTION_LEAPFROG:
            return 'every 2 s leapfrogs 6 px past the nearest enemy within 70 px in front'
        elif _sw2 is Mechanic.SHELL_GAP_JUMP:
            return 'every 3 s jumps forward by its gap: 140, 70, 35, then 18 px'
        elif _sw2 is Mechanic.HEAP_SHIELD:
            return 'enemies on its route up to 90 px behind it take 50% damage; itself Lead-type'
        elif _sw2 is Mechanic.RADIX_PHASES:
            return 'layers 8-7 plain; layers 6 and below are armoured phases (Lead-type: Sharp cannot hurt it)'
        elif _sw2 is Mechanic.BUCKET_STORE:
            return 'every 1 s stores non-boss enemies with base HP <= 5 within 30 px (max 6); releases them on death; leaks them if it leaks'
        else:
            if e is EnemyType.SINGLY_LINKED_LIST:
                return 'fast'
            if e is EnemyType.TIMSORT:
                return 'fast + splits into Merge Sort and Insertion Sort'
            if e.has_children():
                return 'splits when destroyed'
            return '-'
